+package tools.jackson.databind.ser.filter;
+
+import java.util.LinkedHashMap;
+import java.util.Map;
+
+import org.junit.jupiter.api.Test;
+
+import com.fasterxml.jackson.annotation.JsonInclude;
+
+import tools.jackson.databind.ObjectMapper;
+import tools.jackson.databind.testutil.DatabindTestUtil;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+// [databind#6101]: a NON_EMPTY Map property whose entries are all removed by a
+// CUSTOM content filter should be treated as empty and omitted, matching the
+// behavior for content=NON_EMPTY and the (already correct) write path.
+public class JsonIncludeMapContentFilter6101Test extends DatabindTestUtil
+{
+    // equals() returns true for values the content filter should suppress
+    static class FooFilter {
+        @Override
+        public boolean equals(Object other) {
+            return "foo".equals(other);
+        }
+
+        @Override
+        public int hashCode() { return 0; }
+    }
+
+    // Statically-typed value serializer (String) -> isEmpty() static-serializer loop
+    static class Bean {
+        @JsonInclude(value = JsonInclude.Include.NON_EMPTY,
+                content = JsonInclude.Include.CUSTOM,
+                contentFilter = FooFilter.class)
+        public Map<String, String> stuff = new LinkedHashMap<>();
+
+        public Bean add(String key, String value) {
+            stuff.put(key, value);
+            return this;
+        }
+    }
+
+    // Dynamically-resolved value serializer (Object) -> isEmpty() fallback loop
+    static class DynBean {
+        @JsonInclude(value = JsonInclude.Include.NON_EMPTY,
+                content = JsonInclude.Include.CUSTOM,
+                contentFilter = FooFilter.class)
+        public Map<String, Object> stuff = new LinkedHashMap<>();
+
+        public DynBean add(String key, Object value) {
+            stuff.put(key, value);
+            return this;
+        }
+    }
+
+    private final ObjectMapper MAPPER = new ObjectMapper();
+
+    // Before the fix this produced {"stuff":{}} because MapSerializer.isEmpty()
+    // compared the content filter to the whole Map instead of to each entry value.
+    @Test
+    public void mapEmptyAfterContentFilter() throws Exception {
+        Bean bean = new Bean().add("a", "foo").add("b", "foo");
+        assertEquals("{}", MAPPER.writeValueAsString(bean));
+    }
+
+    @Test
+    public void mapKeepsSurvivingEntries() throws Exception {
+        Bean bean = new Bean().add("a", "foo").add("b", "keep");
+        assertEquals("""
+                {"stuff":{"b":"keep"}}""",
+                MAPPER.writeValueAsString(bean));
+    }
+
+    @Test
+    public void genuinelyEmptyMapOmitted() throws Exception {
+        assertEquals("{}", MAPPER.writeValueAsString(new Bean()));
+    }
+
+    // Same bug on the fallback loop taken when the value serializer is not
+    // statically known (Map<String,Object>).
+    @Test
+    public void dynamicValueMapEmptyAfterContentFilter() throws Exception {
+        DynBean bean = new DynBean().add("a", "foo").add("b", "foo");
+        assertEquals("{}", MAPPER.writeValueAsString(bean));
+    }
+
+    @Test
+    public void dynamicValueMapKeepsSurvivingEntries() throws Exception {
+        DynBean bean = new DynBean().add("a", "foo").add("b", "keep");
+        assertEquals("""
+                {"stuff":{"b":"keep"}}""",
+                MAPPER.writeValueAsString(bean));
+    }
+}

problem_statement:
`@JsonInclude(NON_EMPTY, content=CUSTOM)` does not omit a Map property after all entries are filtered

### Search before asking

- [x] I searched in the [issues](https://github.com/FasterXML/jackson-databind/issues) and found nothing similar.

### Describe the bug

When `@JsonInclude(value=NON_EMPTY, content=CUSTOM, contentFilter=...)` is applied to a `Map` property, a Map whose entries are all filtered out should be omitted. Instead, the property is written as an empty object: `{"stuff":{}}`.

`MapSerializer.isEmpty()` applies the content filter's `equals()` to the whole `Map`, rather than to each entry value. The property is therefore considered non-empty and written; the write path then correctly filters every entry, leaving `{}`.

### Version Information

Reproduced on current `3.x` (`3.3.0-SNAPSHOT`). The same two comparisons are also present on current `2.x`.

### Reproduction

```java
static class FooFilter {
    @Override
    public boolean equals(Object other) {
        return "foo".equals(other);
    }
}

static class Bean {
    @JsonInclude(value = JsonInclude.Include.NON_EMPTY,
            content = JsonInclude.Include.CUSTOM,
            contentFilter = FooFilter.class)
    public Map<String, String> stuff = new LinkedHashMap<>();
}

Bean bean = new Bean();
bean.stuff.put("a", "foo");
bean.stuff.put("b", "foo");
String json = new ObjectMapper().writeValueAsString(bean);
// actual: {"stuff":{}}
```

A Map with at least one surviving entry is already handled correctly; for example, `{"stuff":{"b":"keep"}}`.

### Expected behavior

Once the content filter excludes every entry, the property should be treated as empty because its effective Map content is empty.

```json
{}
```

### Additional context

The write path (`serializeOptionalFields`) already compares the filter with each entry value. Only the two `isEmpty()` loops compare it with the whole `Map`.

A focused fix would pass entry values, rather than the `Map` object, to the content filter during the emptiness check. A stateful filter could therefore observe a different call count or order. Is that compatibility impact acceptable for `contentFilter`?

If the intended behavior is to omit the property once all content is filtered, I can provide a focused two-line patch with static and dynamic regression tests.
